package com.learnknow.access;
import jakarta.persistence.*; import jakarta.validation.Valid; import jakarta.validation.constraints.NotNull; import org.springframework.boot.*; import org.springframework.boot.autoconfigure.SpringBootApplication; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
@SpringBootApplication public class AccessServiceApplication {public static void main(String[]a){SpringApplication.run(AccessServiceApplication.class,a);}@Entity public static class Enrollment{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; public Long userId;public Long courseId;public String status="ACTIVE";public Instant enrolledAt=Instant.now();} @org.springframework.stereotype.Repository public interface Repo extends JpaRepository<Enrollment,Long>{List<Enrollment> findByUserId(Long id);Optional<Enrollment> findByUserIdAndCourseId(Long u,Long c);} public record Request(@NotNull Long userId,@NotNull Long courseId){} @RestController @RequestMapping("/api/access") public static class Controller{final EnrollmentRepository repo;Controller(EnrollmentRepository r){repo=r;}@PostMapping("/enroll") @ResponseStatus(HttpStatus.CREATED) Enrollment enroll(@Valid @RequestBody Request r){Enrollment e=repo.findByUserIdAndCourseId(r.userId(),r.courseId()).orElseGet(Enrollment::new);e.userId=r.userId();e.courseId=r.courseId();e.status="ACTIVE";return repo.save(e);}@GetMapping("/user/{userId}") List<Enrollment> user(@PathVariable Long userId){return repo.findByUserId(userId);}@GetMapping("/check/{userId}/{courseId}") Map<String,Object> check(@PathVariable Long userId,@PathVariable Long courseId){boolean active=repo.findByUserIdAndCourseId(userId,courseId).map(e->"ACTIVE".equals(e.status)).orElse(false);return Map.of("userId",userId,"courseId",courseId,"enrolled",active);}@PostMapping("/validate") Map<String,Object> validate(@Valid @RequestBody Request r){return check(r.userId(),r.courseId());}}}
